<?php
require_once __DIR__.'/EmailTransport.php';require_once __DIR__.'/SecurityMailDelivery.php';
final class EmailQueueWorker {
    private PDO $db;private $sender;private bool $ready;
    public function __construct(PDO $db,?callable $sender=null,?bool $ready=null){$this->db=$db;$this->sender=$sender??[new EmailTransport,'send'];$this->ready=$ready??EmailConfiguration::ready();}
    public function process(int $limit=10,?int $onlyId=null):array {
        $result=['sent'=>0,'retrying'=>0,'failed'=>0,'paused'=>!$this->ready];if(!$this->ready)return $result;
        $lock='guidance_mail_'.substr(hash('sha256',(string)$this->db->query('SELECT DATABASE()')->fetchColumn()),0,24);$q=$this->db->prepare('SELECT GET_LOCK(?,0)');$q->execute([$lock]);if(!(int)$q->fetchColumn())return $result;
        try{
            $this->db->exec("UPDATE email_outbox SET body_html='' WHERE recipient_policy='verification' AND status IN ('sent','failed')");
            $this->db->exec("UPDATE email_outbox SET status='failed',last_error='Delivery was interrupted. Review before retrying.',lease_token=NULL,lease_until=NULL WHERE status='processing' AND lease_until<NOW()");
            $where="status='pending' AND attempts<5 AND (send_after IS NULL OR send_after<=NOW())";$params=[];if($onlyId!==null){$where.=' AND id=?';$params[]=$onlyId;}$q=$this->db->prepare('SELECT * FROM email_outbox WHERE '.$where.' ORDER BY (recipient_policy=\'verification\') DESC,id LIMIT '.min(20,max(1,$limit)));$q->execute($params);$rows=$q->fetchAll(PDO::FETCH_ASSOC);
            foreach($rows as $row){$id=(int)$row['id'];$token=bin2hex(random_bytes(16));$q=$this->db->prepare("UPDATE email_outbox SET status='processing',attempts=attempts+1,lease_token=?,lease_until=DATE_ADD(NOW(),INTERVAL 10 MINUTE) WHERE id=? AND status='pending'");$q->execute([$token,$id]);if($q->rowCount()!==1)continue;
                try{$u=$this->db->prepare('SELECT email,password,is_active,archived FROM users WHERE id=?');$u->execute([$row['user_id']]);$user=$u->fetch(PDO::FETCH_ASSOC);if(!$user||!(int)$user['is_active']||(int)$user['archived']){$this->db->prepare("UPDATE email_outbox SET status='failed',body_html=IF(recipient_policy='verification','',body_html),last_error='The recipient account or email address changed.',lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?")->execute([$id,$token]);$result['failed']++;continue;}
                    ($this->sender)($row['to_email'],$row['subject'],SecurityMailDelivery::body($this->db,$row,$user),$row['dedupe_key']?:'outbox:'.$id);$this->db->prepare("UPDATE email_outbox SET status='sent',sent_at=NOW(),body_html=IF(recipient_policy='verification','',body_html),last_error=NULL,lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?")->execute([$id,$token]);$result['sent']++;
                }catch(SecurityMailExpired $e){$this->db->prepare("UPDATE email_outbox SET status='failed',body_html=IF(recipient_policy='verification','',body_html),last_error=?,lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?")->execute([$e->getMessage(),$id,$token]);$result['failed']++;}catch(Throwable $e){$attempt=(int)$row['attempts']+1;$failed=$attempt>=5;$verification=($row['recipient_policy']??'account')==='verification';$wait=$verification?min(120,30*(2**max(0,$attempt-1))):min(240,5*(2**max(0,$attempt-1)));$safe=$e instanceof RuntimeException&&in_array($e->getMessage(),['Mail server authentication failed. Check the account and app password.','Mail server connection failed. Check the server, port and encryption.','Recipient address is invalid.','The mail server did not confirm delivery. Review mail settings before retrying.'],true)?$e->getMessage():'Email delivery failed. Check mail settings.';$this->db->prepare('UPDATE email_outbox SET status=?,send_after=DATE_ADD(NOW(),INTERVAL '.$wait.' '.($verification?'SECOND':'MINUTE').'),body_html=IF(recipient_policy=\'verification\' AND '.($failed?'1':'0').',\'\',body_html),last_error=?,lease_token=NULL,lease_until=NULL WHERE id=? AND lease_token=?')->execute([$failed?'failed':'pending',$safe,$id,$token]);$result[$failed?'failed':'retrying']++;}
            }
            $this->db->exec("INSERT INTO system_settings(setting_key,setting_value,updated_at) VALUES('email_worker_last_run',1,NOW()) ON DUPLICATE KEY UPDATE setting_value=1,updated_at=NOW()");
        }finally{$this->db->prepare('SELECT RELEASE_LOCK(?)')->execute([$lock]);}return $result;
    }
}
